from marshmallow import Schema, fields

class UserSchema(Schema):
    username = fields.Str()
    is_owner = fields.Method("get_is_owner")

    def get_is_owner(self, obj):
        # Access the user passed via the context dictionary
        current_user = self.context.get("current_user")
        if not current_user:
            return False
        return obj.id == current_user.id

# Usage
class UserObject:
    def __init__(self, id, username):
        self.id = id
        self.username = username

class CurrentUser:
    def __init__(self, id):
        self.id = id

user_obj = UserObject(id=1, username="johndoe")
current_user = CurrentUser(id=1)

schema = UserSchema(context={"current_user": current_user})
result = schema.dump(user_obj)
print(result) # {'username': 'johndoe', 'is_owner': True}
